function onResponse(context, url, request, response) {
  // Cut the body to a third of its length while leaving Content-Length
  // untouched, which is what a dropped packet mid-transfer looks like.
  const body = response.bodyAsString();
  response.body = body.substring(0, Math.floor(body.length / 3));
  return response;
}

function onResponse(context, url, request, response) {
  delete response.headers['X-Request-ID'];
  return response;
}
